<script setup>
import { reactive } from 'vue'
import { useRouter } from 'vue-router'
import { useLearnerStore } from '@/stores/learner'
const learner=useLearnerStore(),router=useRouter(),form=reactive({...learner.profile})
function begin(){learner.saveOnboarding({...form,name:form.name.trim().slice(0,30)});router.push('/placement')}
</script>
<template><section class="intro-form"><span class="section-label">只记录你的需要</span><h1>先简单认识一下。</h1><p class="muted">这些信息帮助 Alex 选择语气和话题。实际起点由接下来的词汇测评决定。</p><form @submit.prevent="begin"><label class="field">怎么称呼你（可选）<input v-model="form.name" maxlength="30" placeholder="你的名字"/></label><div class="form-pair"><label class="field">身份<select v-model="form.ageGroup"><option value="child">小学生</option><option value="teen">中学生</option><option value="adult">成人</option></select></label><label class="field">现在的英语感觉<select v-model="form.selfLevel"><option value="new">刚开始，从简单的来</option><option value="little">认识一些常用词</option><option value="basic">能读简单句子</option><option value="comfortable">日常阅读比较轻松</option></select></label></div><label class="field">最想练什么<select v-model="form.goal"><option value="speaking">日常听懂与开口</option><option value="exam">配合学校学习</option><option value="travel">旅行交流</option><option value="interest">用英语聊兴趣</option></select></label><p class="notice">共30题，覆盖原表10个模块。不用猜，遇到不会的词直接选“我不会”。</p><button class="btn btn-primary" type="submit">进入850词入学测</button></form></section></template>
